        parts = []
        start = 0
        for p in lines:
            if start < p:
                parts.append((start, p))
            start = p + 1
        if start < length:
            parts.append((start, length))
        return parts

    def setup(lines, length):
        if not lines:
            return length, set(), [(0, length)]
        if len(lines) > 1:
            gaps = [b - a for a, b in zip(lines, lines[1:])]
            period = Counter(gaps).most_common(1)[0][0]
        else:
            period = lines[0] + 1
        return period, {p % period for p in lines}, regions(length, lines)

    rp, rsep, rregions = setup(row_lines, h)
    cp, csep, cregions = setup(col_lines, w)

    # Choose the tile with the most non-background cells as the repeating source.
    candidates = [
        (r0, r1, c0, c1)
        for r0, r1 in rregions
        for c0, c1 in cregions
    ]
    if not candidates:
        return [row[:] for row in grid]

    counts = Counter(
        grid[r][c]
        for r0, r1, c0, c1 in candidates
        for r in range(r0, r1)
        for c in range(c0, c1)
    )
    background = counts.most_common(1)[0][0]

    def density(box):
        r0, r1, c0, c1 = box
        return sum(grid[r][c] != background
                   for r in range(r0, r1) for c in range(c0, c1))

    sr0, sr1, sc0, sc1 = max(candidates, key=density)
    out = [row[:] for row in grid]

    for r in range(h):
        rpidx = r % rp
        for c in range(w):
            cpidx = c % cp
            if rpidx in rsep:
                out[r][c] = grid[row_lines[0]][c]
            elif cpidx in csep:
