def transform(grid):
    h, w = len(grid), len(grid[0])

    # Uniform full rows and columns are tile dividers.
    row_divs = [r for r in range(h) if len(set(grid[r])) == 1]
    col_divs = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def segments(size, dividers):
        result = []
        start = 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    rows = segments(h, row_divs)
    cols = segments(w, col_divs)
    tiles = [(r0, r1, c0, c1) for r0, r1 in rows for c0, c1 in cols]

    # The tile with the most cells differing from the common background is the motif.
    from collections import Counter
    counts = Counter(grid[r][c] for r0, r1, c0, c1 in tiles
                     for r in range(r0, r1) for c in range(c0, c1))
    background = counts.most_common(1)[0][0]

    def score(tile):
        r0, r1, c0, c1 = tile
        return sum(grid[r][c] != background
                   for r in range(r0, r1) for c in range(c0, c1))

    sr0, sr1, sc0, sc1 = max(tiles, key=score)
    motif_h, motif_w = sr1 - sr0, sc1 - sc0
    out = [row[:] for row in grid]

    for r0, r1 in rows:
        for c0, c1 in cols:
            if (r0, r1, c0, c1) == (sr0, sr1, sc0, sc1):
                continue
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = grid[sr0 + (r - r0) % motif_h][sc0 + (c - c0) % motif_w]

    return out
